    18	    public Price calculate(Room room, NewReservation stay) {
    19	        int nights = 0;
    20	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    21	        for (LocalDate night = stay.checkIn(); night.isBefore(stay.checkOut()); night = night.plusDays(1)) {
    22	            subtotal = subtotal.add(nightPrice(room, night));
    23	            nights++;
    24	        }
    25	        Price seasonal = new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
    26	        return stay.ratePlan().price(stay, room, seasonal);
    27	    }
